
"use client";

import { useEffect, useState } from "react";
import { Plus, Trash2, Loader2, ClipboardPaste, RefreshCw } from "lucide-react";
import api from "../../../../../lib/axios";
import {
  getClassOptions,
  getSubjectOptions,
} from "../../../../../lib/options";

/* =====================================================
   TYPES
===================================================== */

type Row = {
  firstName: string;
  middleName: string;
  lastName: string;

  email: string;
  phone: string;

  // Generated by backend. Never manually entered.
  employeeId: string;

  qualification: string;
  designation: string;

  subjectIds: string[];
  classIds: string[];

  gender: "male" | "female";

  address: string;
  dateOfBirth: string;
  maritalStatus: string;

  stateOfOrigin: string;
  lga: string;
  nationality: string;

  employmentDate: string;
  employmentType: string;

  emergencyName: string;
  emergencyPhone: string;

  bloodGroup: string;
  genotype: string;
  nin: string;

  isActive: boolean;
  status: "active" | "inactive";

  password: string;
};

type ClassOption = {
  _id: string;
  name: string;
};

type SubjectOption = {
  _id: string;
  name: string;
};

type BulkResult = {
  total?: number;
  created?: number;
  updated?: number;
  failed?: number;
  results?: Array<{
    row: number;
    email: string;
    employeeId?: string;
    action: "created" | "updated" | "failed";
    error?: string;
  }>;
};

/* =====================================================
   EMPTY ROW
===================================================== */

function createEmptyRow(): Row {
  return {
    firstName: "",
    middleName: "",
    lastName: "",

    email: "",
    phone: "",

    employeeId: "",

    qualification: "",
    designation: "",

    subjectIds: [],
    classIds: [],

    gender: "male",

    address: "",
    dateOfBirth: "",
    maritalStatus: "",

    stateOfOrigin: "",
    lga: "",
    nationality: "Nigerian",

    employmentDate: "",
    employmentType: "full_time",

    emergencyName: "",
    emergencyPhone: "",

    bloodGroup: "",
    genotype: "",
    nin: "",

    isActive: true,
    status: "active",

    password: "",
  };
}

/* =====================================================
   COMPONENT
===================================================== */

export default function TeacherBulkEntryPage() {
  const [rows, setRows] = useState<Row[]>([
    createEmptyRow(),
  ]);

  const [classes, setClasses] = useState<ClassOption[]>([]);
  const [subjects, setSubjects] = useState<SubjectOption[]>([]);

  const [pasteText, setPasteText] = useState("");
  const [pasteMessage, setPasteMessage] = useState("");

  const [loading, setLoading] = useState(false);
  const [fetching, setFetching] = useState(true);

  const [error, setError] = useState("");
  const [saveResult, setSaveResult] = useState<BulkResult | null>(null);

  /* =====================================================
     LOAD SCHOOL OPTIONS
  ===================================================== */

  async function loadOptions() {
    try {
      setFetching(true);
      setError("");

      const [classRes, subjectRes] = await Promise.all([
        getClassOptions(),
        getSubjectOptions(),
      ]);

      setClasses(classRes || []);
      setSubjects(subjectRes || []);
    } catch (err: any) {
      console.error("Failed to load teacher options:", err);

      setError(
        err?.response?.data?.message ||
          "Unable to load school classes and subjects."
      );
    } finally {
      setFetching(false);
    }
  }

  useEffect(() => {
    loadOptions();
  }, []);

  /* =====================================================
     ROW ACTIONS
  ===================================================== */

  function addRow() {
    setRows((previous) => [
      ...previous,
      createEmptyRow(),
    ]);

    setError("");
    setSaveResult(null);
  }

  function removeRow(index: number) {
    setRows((previous) =>
      previous.length === 1
        ? [createEmptyRow()]
        : previous.filter((_, i) => i !== index)
    );

    setError("");
    setSaveResult(null);
  }

  function updateRow<K extends keyof Row>(
    index: number,
    field: K,
    value: Row[K]
  ) {
    setRows((previous) =>
      previous.map((row, i) =>
        i === index
          ? { ...row, [field]: value }
          : row
      )
    );

    setSaveResult(null);
  }

  function toggleMultiSelect(
    index: number,
    field: "classIds" | "subjectIds",
    value: string
  ) {
    setRows((previous) =>
      previous.map((row, i) => {
        if (i !== index) return row;

        const exists = row[field].includes(value);

        return {
          ...row,
          [field]: exists
            ? row[field].filter((id) => id !== value)
            : [...row[field], value],
        };
      })
    );

    setSaveResult(null);
  }

  /* =====================================================
     PASTE IMPORT
     
     Column order:
     First | Middle | Last | Email | Phone |
     Qualification | Designation | Gender | DOB | State
  ===================================================== */

  function importPastedTeachers() {
    setError("");
    setPasteMessage("");
    setSaveResult(null);

    if (!pasteText.trim()) {
      setError("Paste teacher records first.");
      return;
    }

    const lines = pasteText
      .split(/\r?\n/)
      .filter((line) => line.trim().length > 0);

    if (!lines.length) {
      setError("No teacher records found.");
      return;
    }

    const firstLine = lines[0].toLowerCase();

    const hasHeader =
      firstLine.includes("first") &&
      (
        firstLine.includes("last") ||
        firstLine.includes("email")
      );

    const dataLines = hasHeader
      ? lines.slice(1)
      : lines;

    if (!dataLines.length) {
      setError("The pasted content contains only a header.");
      return;
    }

    const importedRows: Row[] = dataLines.map((line) => {
      const columns = line.split("\t");

      const gender =
        columns[7]?.trim().toLowerCase() === "female"
          ? "female"
          : "male";

      return {
        ...createEmptyRow(),

        firstName: columns[0]?.trim() || "",
        middleName: columns[1]?.trim() || "",
        lastName: columns[2]?.trim() || "",

        email: columns[3]?.trim() || "",
        phone: columns[4]?.trim() || "",

        qualification: columns[5]?.trim() || "",
        designation: columns[6]?.trim() || "",

        gender,

        dateOfBirth: columns[8]?.trim() || "",
        stateOfOrigin: columns[9]?.trim() || "",
      };
    });

    const invalidRows = importedRows
      .map((row, index) => ({
        row,
        number: index + 1,
      }))
      .filter(
        ({ row }) =>
          !row.firstName ||
          !row.lastName ||
          !row.email
      );

    if (invalidRows.length) {
      setError(
        `Check pasted rows: ${invalidRows
          .map((item) => item.number)
          .join(", ")}. First name, last name and email are required.`
      );
      return;
    }

    setRows((previous) => {
      const existingRows = previous.filter(
        (row) =>
          row.firstName.trim() ||
          row.lastName.trim() ||
          row.email.trim()
      );

      return [
        ...existingRows,
        ...importedRows,
      ];
    });

    setPasteMessage(
      `${importedRows.length} teacher(s) imported. Now select subjects, classes and enter passwords.`
    );

    setPasteText("");
  }

  /* =====================================================
     VALIDATION
  ===================================================== */

  function validate() {
    const filledRows = rows.filter(
      (row) =>
        row.firstName.trim() ||
        row.lastName.trim() ||
        row.email.trim()
    );

    if (!filledRows.length) {
      return "Add or paste at least one teacher.";
    }

    for (let index = 0; index < filledRows.length; index++) {
      const row = filledRows[index];
      const rowNumber = index + 1;

      if (!row.firstName.trim()) {
        return `Row ${rowNumber}: First name is required.`;
      }

      if (!row.lastName.trim()) {
        return `Row ${rowNumber}: Last name is required.`;
      }

      const email = row.email.trim();

      if (
        !email ||
        !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
      ) {
        return `Row ${rowNumber}: Enter a valid email address.`;
      }

      if (!row.password.trim()) {
        return `Row ${rowNumber}: Password is required.`;
      }

      if (row.password.length < 6) {
        return `Row ${rowNumber}: Password must contain at least 6 characters.`;
      }

      if (!row.subjectIds.length) {
        return `Row ${rowNumber}: Select at least one subject.`;
      }

      if (!row.classIds.length) {
        return `Row ${rowNumber}: Select at least one class.`;
      }
    }

    const emails = filledRows.map(
      (row) => row.email.trim().toLowerCase()
    );

    if (new Set(emails).size !== emails.length) {
      return "Duplicate email addresses found. Each teacher must have a unique email.";
    }

    return "";
  }

  /* =====================================================
     CLEAN PAYLOAD
  ===================================================== */

  function cleanRow(row: Row) {
    return {
      firstName: row.firstName.trim(),
      middleName: row.middleName.trim(),
      lastName: row.lastName.trim(),

      email: row.email.trim().toLowerCase(),
      phone: row.phone.trim(),

      // Employee ID is deliberately not sent.
      // Backend generates it.

      qualification: row.qualification.trim(),
      designation: row.designation.trim(),

      subjectIds: row.subjectIds,
      classIds: row.classIds,

      gender: row.gender,

      address: row.address.trim(),

      dateOfBirth: row.dateOfBirth || null,
      maritalStatus: row.maritalStatus,

      stateOfOrigin: row.stateOfOrigin.trim(),
      lga: row.lga.trim(),
      nationality: row.nationality,

      employmentDate: row.employmentDate || null,
      employmentType: row.employmentType,

      emergencyName: row.emergencyName.trim(),
      emergencyPhone: row.emergencyPhone.trim(),

      bloodGroup: row.bloodGroup,
      genotype: row.genotype,

      nin: row.nin.trim(),

      isActive: row.status === "active",
      status: row.status,

      password: row.password,
    };
  }

  /* =====================================================
     SAVE TEACHERS
  ===================================================== */

  async function handleSave() {
    const validationError = validate();

    if (validationError) {
      setError(validationError);
      setSaveResult(null);
      return;
    }

    try {
      setLoading(true);
      setError("");
      setSaveResult(null);

      const validRows = rows.filter(
        (row) =>
          row.firstName.trim() ||
          row.lastName.trim() ||
          row.email.trim()
      );

      const payload = {
        rows: validRows.map(cleanRow),
      };

      const response = await api.post(
        "/teachers/bulk",
        payload
      );

      const result: BulkResult = response.data?.data || {};

      setSaveResult(result);

      const failed = result.failed || 0;

      if (failed === 0) {
        setRows([createEmptyRow()]);
        setPasteMessage("");
      } else {
        // Keep rows visible so failed records can be corrected.
        setRows((previous) => previous);
      }

      const generatedIds = (result.results || [])
        .filter(
          (item) =>
            item.employeeId &&
            item.action !== "failed"
        )
        .map(
          (item) =>
            `${item.email}: ${item.employeeId}`
        );

      alert(
        [
          "Teacher processing completed.",
          `Created: ${result.created || 0}`,
          `Updated: ${result.updated || 0}`,
          `Failed: ${result.failed || 0}`,
          generatedIds.length
            ? `\nGenerated Employee IDs:\n${generatedIds.join("\n")}`
            : "",
        ].join("\n")
      );
    } catch (err: any) {
      console.error("Bulk teacher save failed:", err);

      setError(
        err?.response?.data?.message ||
          "Unable to save teachers. Please try again."
      );
    } finally {
      setLoading(false);
    }
  }

  /* =====================================================
     LOADING
  ===================================================== */

  if (fetching) {
    return (
      <div className="flex min-h-[300px] items-center justify-center gap-3 text-slate-400">
        <Loader2 className="animate-spin" size={20} />
        Loading school classes and subjects...
      </div>
    );
  }

  /* =====================================================
     UI
  ===================================================== */

  return (
    <div className="space-y-6 text-white">
      {/* PAGE HEADER */}

      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">
            Bulk Teacher Entry
          </h1>

          <p className="mt-1 text-sm text-slate-400">
            Paste teacher records, assign subjects and classes,
            and create teacher login accounts.
          </p>
        </div>

        <button
          type="button"
          onClick={loadOptions}
          className="btn-secondary inline-flex items-center gap-2"
        >
          <RefreshCw size={16} />
          Refresh Options
        </button>
      </div>

      {/* ERROR */}

      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 p-3 text-sm text-red-300">
          {error}
        </div>
      )}

      {/* SUCCESS SUMMARY */}

      {saveResult && (
        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 p-4">
          <h3 className="font-semibold text-emerald-300">
            Teacher import result
          </h3>

          <div className="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-4">
            <div>
              <p className="text-xs text-slate-400">Total</p>
              <p className="text-xl font-bold">
                {saveResult.total || 0}
              </p>
            </div>

            <div>
              <p className="text-xs text-slate-400">Created</p>
              <p className="text-xl font-bold text-emerald-300">
                {saveResult.created || 0}
              </p>
            </div>

            <div>
              <p className="text-xs text-slate-400">Updated</p>
              <p className="text-xl font-bold">
                {saveResult.updated || 0}
              </p>
            </div>

            <div>
              <p className="text-xs text-slate-400">Failed</p>
              <p className="text-xl font-bold text-red-300">
                {saveResult.failed || 0}
              </p>
            </div>
          </div>

          {saveResult.results?.some(
            (item) => item.action === "failed"
          ) && (
            <div className="mt-4 space-y-2">
              <p className="text-sm font-medium text-red-300">
                Rows requiring correction
              </p>

              {saveResult.results
                .filter((item) => item.action === "failed")
                .map((item, index) => (
                  <p
                    key={`${item.row}-${index}`}
                    className="text-xs text-red-200"
                  >
                    Row {item.row} ({item.email}): {item.error}
                  </p>
                ))}
            </div>
          )}
        </div>
      )}

      {/* PASTE IMPORT */}

      <section className="space-y-4 rounded-2xl border border-white/10 bg-white/[0.03] p-4 sm:p-5">
        <div className="flex items-center gap-2">
          <ClipboardPaste size={20} className="text-cyan-400" />

          <div>
            <h2 className="font-semibold">
              Paste Teachers from Excel or Google Sheets
            </h2>

            <p className="text-xs text-slate-400">
              Copy rows from your spreadsheet and paste them below.
            </p>
          </div>
        </div>

        <div className="rounded-lg bg-slate-900/80 p-3 text-xs text-slate-300">
          <p className="font-semibold text-slate-200">
            Required paste column order
          </p>

          <p className="mt-1 break-words">
            First | Middle | Last | Email | Phone | Qualification |
            Designation | Gender | DOB | State
          </p>

          <p className="mt-2 text-slate-400">
            Do not include Employee ID. EduTrack generates it.
            Subjects, classes and passwords are completed below.
          </p>
        </div>

        <textarea
          value={pasteText}
          onChange={(event) => setPasteText(event.target.value)}
          rows={7}
          placeholder={`First\tMiddle\tLast\tEmail\tPhone\tQualification\tDesignation\tGender\tDOB\tState
John\tA\tTali\tjohn@example.com\t08012345678\tB.Ed\tTeacher\tMale\t1990-01-01\tKaduna`}
          className="w-full rounded-xl border border-white/10 bg-slate-950 p-3 text-sm text-white outline-none placeholder:text-slate-600 focus:border-cyan-500"
        />

        <div className="flex flex-wrap items-center gap-3">
          <button
            type="button"
            onClick={importPastedTeachers}
            className="btn-secondary inline-flex items-center gap-2"
          >
            <ClipboardPaste size={16} />
            Import Pasted Rows
          </button>

          <button
            type="button"
            onClick={() => {
              setPasteText("");
              setPasteMessage("");
            }}
            className="text-sm text-slate-400 hover:text-white"
          >
            Clear Paste Box
          </button>
        </div>

        {pasteMessage && (
          <p className="text-sm text-emerald-400">
            {pasteMessage}
          </p>
        )}
      </section>

      {/* TEACHER TABLE */}

      <section className="space-y-3">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h2 className="text-lg font-semibold">
              Teacher Records
            </h2>

            <p className="text-xs text-slate-400">
              {rows.length} row(s). Select subjects and classes,
              then enter a password for each teacher.
            </p>
          </div>

          <button
            type="button"
            onClick={addRow}
            className="btn-secondary inline-flex items-center gap-2"
          >
            <Plus size={16} />
            Add Row
          </button>
        </div>

        <div className="overflow-x-auto rounded-xl border border-white/10">
          <table className="min-w-[2700px] border-collapse text-sm">
            <thead className="bg-white/5 text-slate-300">
              <tr>
                <th className="p-3 text-left">First</th>
                <th className="p-3 text-left">Middle</th>
                <th className="p-3 text-left">Last</th>
                <th className="p-3 text-left">Email</th>
                <th className="p-3 text-left">Phone</th>
                <th className="p-3 text-left">Employee ID</th>
                <th className="p-3 text-left">Qualification</th>
                <th className="p-3 text-left">Designation</th>
                <th className="p-3 text-left">Gender</th>
                <th className="p-3 text-left">DOB</th>
                <th className="p-3 text-left">State</th>
                <th className="p-3 text-left">Subjects</th>
                <th className="p-3 text-left">Classes</th>
                <th className="p-3 text-left">Status</th>
                <th className="p-3 text-left">Password</th>
                <th className="p-3 text-center">Action</th>
              </tr>
            </thead>

            <tbody>
              {rows.map((row, index) => (
                <tr
                  key={index}
                  className="border-t border-white/10 align-top"
                >
                  {/* FIRST NAME */}

                  <td className="min-w-[140px] p-2">
                    <input
                      className="input w-full"
                      value={row.firstName}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "firstName",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* MIDDLE NAME */}

                  <td className="min-w-[140px] p-2">
                    <input
                      className="input w-full"
                      value={row.middleName}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "middleName",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* LAST NAME */}

                  <td className="min-w-[140px] p-2">
                    <input
                      className="input w-full"
                      value={row.lastName}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "lastName",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* EMAIL */}

                  <td className="min-w-[220px] p-2">
                    <input
                      type="email"
                      className="input w-full"
                      value={row.email}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "email",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* PHONE */}

                  <td className="min-w-[150px] p-2">
                    <input
                      className="input w-full"
                      value={row.phone}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "phone",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* GENERATED EMPLOYEE ID */}

                  <td className="min-w-[160px] p-2">
                    <div className="rounded-lg border border-dashed border-cyan-500/30 bg-cyan-500/5 px-3 py-2 text-xs text-cyan-300">
                      Auto-generated on save
                    </div>
                  </td>

                  {/* QUALIFICATION */}

                  <td className="min-w-[180px] p-2">
                    <input
                      className="input w-full"
                      value={row.qualification}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "qualification",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* DESIGNATION */}

                  <td className="min-w-[180px] p-2">
                    <input
                      className="input w-full"
                      value={row.designation}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "designation",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* GENDER */}

                  <td className="min-w-[120px] p-2">
                    <select
                      className="input w-full"
                      value={row.gender}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "gender",
                          event.target.value as "male" | "female"
                        )
                      }
                    >
                      <option value="male">Male</option>
                      <option value="female">Female</option>
                    </select>
                  </td>

                  {/* DATE OF BIRTH */}

                  <td className="min-w-[150px] p-2">
                    <input
                      type="date"
                      className="input w-full"
                      value={row.dateOfBirth}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "dateOfBirth",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* STATE */}

                  <td className="min-w-[160px] p-2">
                    <input
                      className="input w-full"
                      value={row.stateOfOrigin}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "stateOfOrigin",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* SUBJECTS */}

                  <td className="min-w-[320px] p-2">
                    <div className="flex flex-wrap gap-1.5">
                      {subjects.map((subject) => {
                        const selected =
                          row.subjectIds.includes(subject._id);

                        return (
                          <button
                            key={subject._id}
                            type="button"
                            onClick={() =>
                              toggleMultiSelect(
                                index,
                                "subjectIds",
                                subject._id
                              )
                            }
                            className={`rounded-lg border px-2 py-1.5 text-xs transition ${
                              selected
                                ? "border-cyan-400 bg-cyan-500/20 text-cyan-300"
                                : "border-white/10 text-slate-300 hover:border-cyan-500/50"
                            }`}
                          >
                            {selected ? "✓ " : ""}
                            {subject.name}
                          </button>
                        );
                      })}

                      {!subjects.length && (
                        <span className="text-xs text-amber-400">
                          No subjects found. Create subjects first.
                        </span>
                      )}
                    </div>

                    <p className="mt-2 text-xs text-slate-500">
                      Selected: {row.subjectIds.length}
                    </p>
                  </td>

                  {/* CLASSES */}

                  <td className="min-w-[320px] p-2">
                    <div className="flex flex-wrap gap-1.5">
                      {classes.map((schoolClass) => {
                        const selected =
                          row.classIds.includes(schoolClass._id);

                        return (
                          <button
                            key={schoolClass._id}
                            type="button"
                            onClick={() =>
                              toggleMultiSelect(
                                index,
                                "classIds",
                                schoolClass._id
                              )
                            }
                            className={`rounded-lg border px-2 py-1.5 text-xs transition ${
                              selected
                                ? "border-purple-400 bg-purple-500/20 text-purple-300"
                                : "border-white/10 text-slate-300 hover:border-purple-500/50"
                            }`}
                          >
                            {selected ? "✓ " : ""}
                            {schoolClass.name}
                          </button>
                        );
                      })}

                      {!classes.length && (
                        <span className="text-xs text-amber-400">
                          No classes found. Create classes first.
                        </span>
                      )}
                    </div>

                    <p className="mt-2 text-xs text-slate-500">
                      Selected: {row.classIds.length}
                    </p>
                  </td>

                  {/* STATUS */}

                  <td className="min-w-[130px] p-2">
                    <select
                      className="input w-full"
                      value={row.status}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "status",
                          event.target.value as "active" | "inactive"
                        )
                      }
                    >
                      <option value="active">Active</option>
                      <option value="inactive">Inactive</option>
                    </select>
                  </td>

                  {/* PASSWORD */}

                  <td className="min-w-[170px] p-2">
                    <input
                      type="password"
                      autoComplete="new-password"
                      className="input w-full"
                      placeholder="Min. 6 characters"
                      value={row.password}
                      onChange={(event) =>
                        updateRow(
                          index,
                          "password",
                          event.target.value
                        )
                      }
                    />
                  </td>

                  {/* REMOVE */}

                  <td className="min-w-[80px] p-2 text-center">
                    <button
                      type="button"
                      onClick={() => removeRow(index)}
                      className="mt-2 rounded-lg p-2 text-red-400 hover:bg-red-500/10 hover:text-red-300"
                      title="Remove teacher row"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* TABLE ACTIONS */}

        <div className="flex flex-wrap items-center gap-3">
          <button
            type="button"
            onClick={addRow}
            className="btn-secondary inline-flex items-center gap-2"
          >
            <Plus size={16} />
            Add Row
          </button>

          <button
            type="button"
            onClick={handleSave}
            disabled={loading || fetching}
            className="btn-primary inline-flex items-center gap-2 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? (
              <>
                <Loader2 size={16} className="animate-spin" />
                Saving Teachers...
              </>
            ) : (
              "Save Teachers"
            )}
          </button>
        </div>

        <p className="text-xs text-slate-500">
          Employee IDs are generated by the backend. Passwords are hashed
          before storage. Each teacher's subject and class assignments are
          validated against this school.
        </p>
      </section>
    </div>
  );
}
